function budgetSpeed(H,reserve,draftDistance=0) {
  let low=3,high=H.maxV;
  for(let i=0;i<9;i++) {
    const mid=(low+high)/2;
    if(finishPlan(H,mid,draftDistance,{reserve}).feasible) low=mid;else high=mid;
  }
  return low;
}

